import crypto from "crypto";

// Secret used for signing notification action tokens
function getSigningSecret(): string {
  return (
    process.env.CRON_SECRET ||
    process.env.VAPID_PRIVATE_KEY ||
    "attendx-secure-action-signing-fallback-key-2026"
  );
}

export interface ActionTokenPayload {
  studentId: string;
  date: string;
  period: number;
  subjectCode: string;
  deadlineTime: string;
}

/**
 * Creates a cryptographically secure HMAC-SHA256 signature for a push notification action.
 * This guarantees that:
 * 1. The action payload was generated by the trusted backend.
 * 2. A student cannot tamper with studentId, period, or subjectCode.
 * 3. The deadline cannot be arbitrarily extended by client manipulation.
 */
export function generateActionToken(payload: ActionTokenPayload): string {
  const secret = getSigningSecret();
  const canonicalData = [
    payload.studentId,
    payload.date,
    payload.period.toString(),
    payload.subjectCode,
    payload.deadlineTime,
  ].join("|");

  return crypto.createHmac("sha256", secret).update(canonicalData).digest("hex");
}

/**
 * Verifies that the provided token matches the expected HMAC for the payload.
 * Uses timingSafeEqual to protect against timing attacks.
 */
export function verifyActionToken(
  payload: ActionTokenPayload,
  token: string
): boolean {
  if (!token) return false;
  try {
    const expected = generateActionToken(payload);
    const tokenBuffer = Buffer.from(token, "hex");
    const expectedBuffer = Buffer.from(expected, "hex");

    if (tokenBuffer.length !== expectedBuffer.length) {
      return false;
    }

    return crypto.timingSafeEqual(tokenBuffer, expectedBuffer);
  } catch {
    return false;
  }
}

/**
 * Returns the current date and time components in India Standard Time (Asia/Kolkata).
 */
export function getISTDateTime(dateInput: Date = new Date()): {
  now: Date;
  dayOfWeek: string;
  dateStr: string;
  hour: number;
  minute: number;
} {
  const now = dateInput;
  const istFormatter = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Kolkata",
    weekday: "long",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });

  const parts = istFormatter.formatToParts(now);
  const partMap: Record<string, string> = {};
  for (const p of parts) {
    partMap[p.type] = p.value;
  }

  return {
    now,
    dayOfWeek: partMap.weekday || "Monday",
    dateStr: `${partMap.year}-${partMap.month}-${partMap.day}`,
    hour: parseInt(partMap.hour, 10),
    minute: parseInt(partMap.minute, 10),
  };
}

/**
 * Validates request authorization for internal cron sweep endpoints.
 * Supports:
 * - Authorization: Bearer <CRON_SECRET>
 * - Query parameter: ?key=<CRON_SECRET>
 */
export function validateCronAuthorization(authHeader: string | null, queryKey: string | null): boolean {
  const expectedSecret = process.env.CRON_SECRET;
  if (!expectedSecret) {
    // In local development or testing without CRON_SECRET configured, permit
    if (process.env.NODE_ENV !== "production") {
      return true;
    }
    return false;
  }

  if (authHeader && authHeader === `Bearer ${expectedSecret}`) {
    return true;
  }

  if (queryKey && queryKey === expectedSecret) {
    return true;
  }

  return false;
}
